#!/usr/bin/env python3
"""Preserve cached timestamps only where Git blobs/generated bytes are identical."""
from pathlib import Path
import os
import subprocess

cache = Path('/src/wt/power-r5-integ')
tree = Path('/src/wt/power-r6-integ')
for directory in (cache, tree):
    subprocess.run(['git', '-C', str(directory), 'diff', '--exit-code'], check=True)
old, new = (subprocess.check_output(['git', '-C', str(p), 'write-tree'], text=True).strip()
            for p in (cache, tree))
changed = set(subprocess.check_output(['git', 'diff', '--name-only', '-z', old, new]).decode().split('\0'))
paths = subprocess.check_output(['git', '-C', str(tree), 'ls-files', '-z']).decode().split('\0')
count = 0
for name in paths:
    if not name or name in changed:
        continue
    src, dst = cache / name, tree / name
    if src.is_symlink() or dst.is_symlink() or not src.is_file() or not dst.is_file():
        continue
    stamp = src.stat()
    os.utime(dst, ns=(stamp.st_atime_ns, stamp.st_mtime_ns))
    count += 1
# syncconfig can rewrite identical headers after copying .config. That would
# invalidate every object, despite unchanged configuration and tracked headers.
for name in ('.config', 'include/generated/autoconf.h', 'include/generated/rustc_cfg', 'include/config/auto.conf'):
    src, dst = cache / name, tree / name
    if src.is_file() and dst.is_file() and src.read_bytes() == dst.read_bytes():
        stamp = src.stat()
        os.utime(dst, ns=(stamp.st_atime_ns, stamp.st_mtime_ns))
print(f'Cache timestamps: {count} unchanged tracked files; round-6 delta retains new timestamps')
# A prior interrupted prepare can also regenerate byte-identical arch headers.
for directory in ('include/generated', 'arch/arm64/include/generated'):
    for src in (cache / directory).rglob('*.h'):
        dst = tree / src.relative_to(cache)
        if dst.is_file() and src.read_bytes() == dst.read_bytes():
            stamp = src.stat()
            os.utime(dst, ns=(stamp.st_atime_ns, stamp.st_mtime_ns))
